package com.zycus.procurement.po;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.UniqueConstraint;
import java.time.Instant;

/**
 * Remembers which PO an Idempotency-Key was used for, so a retry (the mobile app retries on
 * timeouts) replays the result instead of approving twice.
 *
 * <p>Keys are generated by the client and are only unique per user, so the unique constraint is
 * (approver_id, idem_key). It is what makes {@link IdempotencyRecordRepository#claim} atomic.
 * Migration: {@code create unique index uk_idempotency_approver_key on idempotency_records
 * (approver_id, idem_key)} and {@code alter table idempotency_records drop column response_status}
 * (replays return the PO's current state).
 */
@Entity
@Table(name = "idempotency_records",
       uniqueConstraints = @UniqueConstraint(name = "uk_idempotency_approver_key",
                                             columnNames = {"approver_id", "idem_key"}))
public class IdempotencyRecord {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "idem_key", nullable = false)
    private String key;

    @Column(name = "approver_id", nullable = false)
    private String approverId;

    @Column(nullable = false)
    private long purchaseOrderId;

    @Column(nullable = false)
    private Instant createdAt = Instant.now();

    protected IdempotencyRecord() {
    }

    public String getKey() {
        return key;
    }

    public String getApproverId() {
        return approverId;
    }

    public long getPurchaseOrderId() {
        return purchaseOrderId;
    }
}
